<div class="ai-assistant" id="aiAssistant"><div class="ai-hint" id="aiHint" hidden>سلام، من دستیار خرید هستم. اگر خواستی با صدای خودت بگو دنبال چه فایلی هستی.</div><button class="ai-fab" id="aiFab" type="button" aria-label="دستیار انتخاب مشاور" title="دستیار انتخاب مشاور" aria-expanded="false" aria-controls="aiPanel"><x-icon name="ai" size="28" /></button><section class="ai-panel" id="aiPanel" hidden aria-live="polite"><div class="ai-panel-head"><div><strong>دستیار خرید</strong><small id="aiStatus">برای شروع روی دکمه میکروفون بزنید</small></div><button id="aiClose" type="button" aria-label="بستن"><x-icon name="close" size="18" /></button></div><div class="ai-orb" id="aiOrb"><span></span></div><div class="ai-live" id="aiLive">منتظر گفت‌وگوی شما هستم</div><button class="ai-mic" id="aiMic" type="button"><x-icon name="ai" size="22" /><span>شروع گفت‌وگوی صوتی</span></button><div class="ai-transcript" id="aiTranscript" aria-live="polite"></div></section></div>
@push('styles')<style>.ai-assistant{position:fixed;left:18px;bottom:calc(env(safe-area-inset-bottom,0px) + 18px);z-index:1200;font-family:inherit}.ai-fab{position:relative;border:0;cursor:pointer;border-radius:999px;width:56px;height:56px;padding:0;background:linear-gradient(135deg,#25cff0 0%,#5b7cf6 38%,#a855f7 68%,#ee2fc0 100%);color:#fff;box-shadow:0 4px 14px #a855f775;display:inline-flex;align-items:center;justify-content:center;transition:.25s}.ai-fab:hover{transform:translateY(-2px) scale(1.04);box-shadow:0 8px 24px #a855f760}.ai-fab:after{content:'';position:absolute;inset:-5px;border-radius:inherit;border:1px solid #a855f730;animation:aiPulse 2.8s infinite}.ai-hint{position:absolute;left:0;bottom:68px;width:250px;padding:12px 14px;border-radius:14px 14px 14px 4px;background:#111827;color:#fff;font-size:11px;line-height:1.9;box-shadow:0 12px 35px #10182825;animation:aiIn .35s ease}.ai-panel{position:absolute;left:0;bottom:68px;width:min(340px,calc(100vw - 30px));background:#fff;border:1px solid #e7e9ef;border-radius:24px;overflow:hidden;box-shadow:0 25px 70px #10182830}.ai-panel-head{display:flex;justify-content:space-between;align-items:center;padding:15px 16px;border-bottom:1px solid #eef0f4}.ai-panel-head strong,.ai-panel-head small{display:block}.ai-panel-head strong{font-size:14px}.ai-panel-head small{font-size:10px;color:#667085;margin-top:3px}.ai-panel-head button{border:0;background:#f4f5f7;width:32px;height:32px;border-radius:9px;cursor:pointer;color:#667085}.ai-orb{width:92px;height:92px;border-radius:50%;margin:24px auto 12px;display:grid;place-items:center;background:radial-gradient(circle,#fff 0 24%,transparent 25%),linear-gradient(135deg,#25cff0,#5b7cf6,#a855f7,#ee2fc0);box-shadow:0 10px 35px #a855f740}.ai-orb span{width:28px;height:28px;border-radius:50%;background:#fff;box-shadow:0 0 0 7px #ffffff40}.ai-orb.listening{animation:aiListen 1s infinite}.ai-live{text-align:center;font-size:12px;color:#475467;min-height:24px;padding:0 15px}.ai-mic{display:flex;align-items:center;justify-content:center;gap:8px;width:calc(100% - 32px);margin:15px 16px 12px;padding:12px;border:0;border-radius:13px;background:#111827;color:#fff;font:inherit;font-weight:800;cursor:pointer}.ai-mic.listening{background:linear-gradient(135deg,#6541d8,#ee2fc0)}.ai-transcript{padding:0 16px 16px;text-align:center;color:#667085;font-size:10px;min-height:18px}@keyframes aiPulse{0%,100%{opacity:.25;transform:scale(.98)}50%{opacity:.8;transform:scale(1.08)}}@keyframes aiListen{50%{transform:scale(1.08);box-shadow:0 10px 45px #ee2fc060}}@keyframes aiIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}@media(max-width:600px){.ai-assistant{left:12px;bottom:calc(env(safe-area-inset-bottom,0px) + 12px)}.ai-panel{width:calc(100vw - 24px)}.ai-hint{width:230px}}</style>@endpush
@push('scripts')<script>(function(){const fab=document.getElementById('aiFab'),panel=document.getElementById('aiPanel'),close=document.getElementById('aiClose'),mic=document.getElementById('aiMic'),status=document.getElementById('aiStatus'),live=document.getElementById('aiLive'),orb=document.getElementById('aiOrb'),hint=document.getElementById('aiHint'),transcript=document.getElementById('aiTranscript');if(!fab)return;let rec=null,listening=false,busy=false;const toggle=open=>{panel.hidden=!open;fab.setAttribute('aria-expanded',open?'true':'false');if(open)hint.hidden=true};fab.onclick=()=>toggle(true);close?.addEventListener('click',()=>toggle(false));function speak(text){if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='fa-IR';u.rate=.95;u.pitch=1;window.speechSynthesis.speak(u)}async function ask(text){if(busy)return;busy=true;status.textContent='در حال بررسی محصولات واقعی…';live.textContent='در حال فکر کردن';try{const r=await fetch('{{ route('ai.chat') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({message:text})});const d=await r.json();const answer=d.message||'فعلاً پاسخ قابل اتکایی ندارم.';transcript.textContent='گفتار شما دریافت شد و پاسخ صوتی پخش می‌شود.';live.textContent=answer;speak(answer);status.textContent='گفت‌وگو ادامه دارد؛ دوباره صحبت کنید';}catch(e){live.textContent='ارتباط با دستیار برقرار نشد.';speak('متأسفم، ارتباط با دستیار برقرار نشد.')}finally{busy=false}}function stop(){if(rec)try{rec.stop()}catch(e){}listening=false;mic.classList.remove('listening');orb.classList.remove('listening');mic.querySelector('span').textContent='شروع گفت‌وگوی صوتی'}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){rec=new SR();rec.lang='fa-IR';rec.interimResults=true;rec.continuous=false;rec.onstart=()=>{listening=true;mic.classList.add('listening');orb.classList.add('listening');status.textContent='دارم گوش می‌دهم…';live.textContent='صحبت کنید'};rec.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++)t+=e.results[i][0].transcript;if(e.results[e.results.length-1].isFinal){stop();ask(t)}};rec.onerror=()=>{stop();live.textContent='صدای شما دریافت نشد؛ دوباره تلاش کنید'};rec.onend=()=>{if(listening)stop()};mic.onclick=()=>{if(listening){stop();return}try{rec.start()}catch(e){}}}else{mic.disabled=true;live.textContent='مرورگر شما ورودی صوتی را پشتیبانی نمی‌کند.'}const visits=Number(localStorage.getItem('ds_visits')||0)+1;localStorage.setItem('ds_visits',visits);let seconds=0;const tick=setInterval(()=>{seconds++;if(seconds===8&&!localStorage.getItem('ds_ai_intro_v2')){hint.hidden=false;localStorage.setItem('ds_ai_intro_v2','1');setTimeout(()=>hint.hidden=true,6000)}if(seconds>30)clearInterval(tick)},1000);window.addEventListener('scroll',()=>{if(window.scrollY>500&&visits>=2&&!localStorage.getItem('ds_ai_behavior_intro')){localStorage.setItem('ds_ai_behavior_intro','1');hint.textContent='اگر بین فایل‌ها مردد هستی، با صدای خودت نیازت را بگو تا راهنمایی‌ات کنم.';hint.hidden=false;setTimeout(()=>hint.hidden=true,6000)}},{passive:true})})();</script>@endpush
